INSERT INTO content (
  content_type, title, slug, excerpt, body,
  og_image, hero_image, hero_image_alt,
  seo_title, seo_description,
  status, is_active, indexable, display_order,
  category, show_on_homepage,
  published_at, created_at, updated_at
) VALUES (
  'SERVICE', 'Ankara VIP Transfer', 'ankara-vip-transfer', 'Ankara Esenboğa Havalimanı ve şehir içi transferlerde Mercedes Vito ve Sprinter ile VIP özel araç hizmeti. Kapıdan kapıya konforlu ulaşım.', '{"version":2,"hero":{"badge":"Ankara VIP Transfer","title":"Ankara VIP Transfer Hizmeti","subtitle":"Ankara Esenboğa Havalimanı transferinden şehir içi VIP ulaşıma kadar — Mercedes Vito ve Sprinter ile profesyonel, konforlu ve güvenilir özel araç hizmeti.","crumb":"Ankara VIP Transfer","ctaPrimary":"Rezervasyon ve Fiyat","ctaSecondary":"Hemen Ara"},"features":["Esenboğa Havalimanı''nda isim tabelasıyla karşılama","Ankara''nın tüm ilçelerine kapıdan kapıya hizmet","Bagaj yardımı dahil — valizlerinizi biz taşırız","Uçuş takibi — gecikmede aracınız sizi bekler","7/24 hizmet — her saatte güvenilir transfer","Deneyimli şoförler, bakımlı Mercedes araçlar"],"seo":{"ogTitle":"Ankara VIP Transfer | Esenboğa Havalimanı Mercedes Araç","ogDescription":"Ankara''da Esenboğa Havalimanı ve şehir içi noktalara Mercedes Vito/Sprinter ile VIP transfer. İsim tabelası, 7/24 hizmet."},"introBody":"Ankara, Türkiye''nin başkenti olarak yoğun iş seyahati ve devlet ziyaretleri ile öne çıkan bir şehirdir. Esenboğa Havalimanı''ndan Kızılay, Çankaya, Atatürk Orman Çiftliği, Bilkent veya Ankara''nın diğer noktalarına ulaşmak için özel araç transferi, toplu taşımaya kıyasla çok daha konforlu ve doğrudan bir seçenek sunar. Şoförümüz isminize hazırladığı tabela ile gidiş kapısında sizi karşılar ve seçtiğiniz adrese kesintisiz ulaştırır.","contentSections":[{"id":"ankara-havalimani-transfer","headingLevel":"h2","heading":"Esenboğa Havalimanı Transfer Hizmeti","body":"Ankara Esenboğa Havalimanı (ESB), şehir merkezine yakın konumuyla ulaşım açısından avantajlıdır. Ancak trafik yoğunluğu ve bagaj durumuna göre özel araç transferi en pratik seçenektir. Şoförümüz uçuş takibi yaparak iniş saatinize göre hazır olur; pasaport kontrolü ve bagaj alımının ardından karşılama alanında bulunacaktır."},{"id":"ankara-sehir-ici-transfer","headingLevel":"h2","heading":"Ankara Şehir İçi VIP Transfer","body":"Kızılay, Çankaya, Beşevler, Ulus, Keçiören, Sincan ve Ankara''nın diğer tüm ilçelerine özel araç hizmeti verilmektedir. Kurumsal toplantılar, devlet kurumları ziyaretleri ve özel etkinlikler için günlük veya saatlik araç tahsisi de yapılabilmektedir."},{"id":"ankara-kurumsal-transfer","headingLevel":"h2","heading":"Kurumsal ve Diplomatik Transferler","body":"Ankara''nın başkent kimliği nedeniyle diplomatik misyon üyeleri, büyükelçilik personeli, yüksek profilli iş insanları ve medya temsilcileri için diskret ve profesyonel transfer hizmetleri sunulabilmektedir. Araç içinde gizlilik ve sessiz çalışma ortamı sağlanır."},{"id":"ankara-istanbul-transfer","headingLevel":"h2","heading":"Ankara–İstanbul Şehirlerarası Transfer","body":"Ankara merkezli ya da İstanbul–Ankara arasında şehirlerarası özel araç transferi de hizmet kapsamımızdadır. İki şehir arasında kapıdan kapıya, kendi programınıza göre konforlu yolculuk yapabilirsiniz."}],"serviceArea":{"title":"Hizmet Verilen Bölgeler","description":"Ankara Esenboğa Havalimanı ve şehrin tüm ilçelerine özel transfer hizmeti sunulmaktadır.","areas":["Kızılay","Çankaya","Ulus","Beşevler","Keçiören","Sincan","Etimesgut","Mamak","Yenimahalle","Bilkent","ODTÜ Kampüsü","Atatürk Orman Çiftliği"]},"faqs":[{"id":"ankara-faq-1","question":"İstanbul''dan Ankara''ya transfer yapıyor musunuz?","answer":"Evet. İstanbul–Ankara ve Ankara–İstanbul arasında şehirlerarası özel araç transferi sunulmaktadır. Kendi adresinizden alım yapılır ve hedef adresinize bırakılırsınız."},{"id":"ankara-faq-2","question":"Esenboğa''dan Ankara şehir merkezine ne kadar sürer?","answer":"Normal trafik koşullarında Esenboğa Havalimanı ile Kızılay merkezi arasındaki mesafe yaklaşık 40–50 dakikalık sürüşe karşılık gelir. Trafik yoğunluğuna göre değişkenlik gösterebilir."},{"id":"ankara-faq-3","question":"Kurumsal fatura düzenleyebiliyor musunuz?","answer":"Evet. Kurumsal ve devlet kuruluşlarına yönelik fatura düzenleme imkânı mevcuttur. Rezervasyon sırasında şirket bilgilerinizi paylaşmanız yeterlidir."},{"id":"ankara-faq-4","question":"Gece geç saatlerde de hizmet alabilir miyim?","answer":"7/24 hizmet sunulmaktadır. Gece geç ya da sabah erken uçuşlarda da Esenboğa''dan karşılama yapılmaktadır."},{"id":"ankara-faq-5","question":"Uçuşum gecikirse ne olur?","answer":"Şoförümüz uçuş takibi yaparak güncel iniş saatinizi takip eder. Gecikme durumunda aracınız sizi beklemeye devam eder."}],"schemaExtras":{"serviceType":"Airport Transfer","openingHours":"Mo-Su 00:00-24:00","availableLanguage":["Turkish","English"]}}'::jsonb,
  '/hero-images/ankara-vip-transfer.jpg', '/hero-images/ankara-vip-transfer.jpg', 'Ankara VIP Transfer',
  'Ankara VIP Transfer | Esenboğa Havalimanı Özel Araç', 'Ankara Esenboğa Havalimanı''ndan ve şehir içi noktalara Mercedes Vito ve Sprinter ile özel VIP transfer hizmeti. 7/24, kapıdan kapıya.',
  'PUBLISHED', true, true, 15,
  'airport', true,
  now(), now(), now()
)
ON CONFLICT (slug) DO NOTHING;

INSERT INTO content (
  content_type, title, slug, excerpt, body,
  og_image, hero_image, hero_image_alt,
  seo_title, seo_description,
  status, is_active, indexable, display_order,
  category, show_on_homepage,
  published_at, created_at, updated_at
) VALUES (
  'SERVICE', 'Antalya VIP Transfer', 'antalya-vip-transfer', 'Antalya Havalimanı ve şehir içi VIP transfer hizmeti. Mercedes Vito ve Sprinter ile otel, villa ve tatil bölgelerine özel araç ulaşımı.', '{"version":2,"hero":{"badge":"Antalya VIP Transfer","title":"Antalya VIP Transfer Hizmeti","subtitle":"Antalya Havalimanı''ndan Kemer, Belek, Side, Alanya ve tüm tatil bölgelerine — Mercedes Vito ve Sprinter ile konforlu, kapıdan kapıya özel VIP transfer.","crumb":"Antalya VIP Transfer","ctaPrimary":"Rezervasyon ve Fiyat","ctaSecondary":"Hemen Ara"},"features":["Antalya Havalimanı çıkışında karşılama tabelası","Kemer, Belek, Side, Alanya ve tüm tatil bölgelerine transfer","Otel, resort ve özel villa kapısına teslim","Bagaj yardımı ve geniş bagaj kapasitesi","Uçuş takibi ile gecikme koruması","7/24 hizmet — tatil sezonunda kesintisiz"],"seo":{"ogTitle":"Antalya VIP Transfer | Kemer, Belek, Side, Alanya","ogDescription":"Antalya Havalimanı''ndan tatil bölgelerine (Kemer, Belek, Side, Alanya) Mercedes araçla özel VIP transfer. Otel ve villa kapısına hizmet."},"introBody":"Antalya, Türkiye''nin en büyük turizm destinasyonlarından biridir ve her yıl milyonlarca turistin uğrak noktasıdır. Antalya Havalimanı''ndan Kemer, Belek, Side veya Alanya''ya ulaşmak için özel araç transferi; tatil sezonunda en konforlu ve doğrudan seçenektir. Şoförümüz isminize hazırladığı tabela ile gidiş kapısında sizi karşılar; valizlerinizi yükler ve seçtiğiniz otel ya da villa adresine sizi bırakır.","contentSections":[{"id":"antalya-havalimani","headingLevel":"h2","heading":"Antalya Havalimanı Karşılama Hizmeti","body":"Antalya Havalimanı (AYT) Terminal 1 ve Terminal 2''den karşılama yapılmaktadır. Uçuş bilgileriniz ve terminal numaranızı rezervasyon sırasında paylaşmanız yeterlidir; şoförümüz tam zamanında gidiş kapısında olur."},{"id":"antalya-tatil-bolgeleri","headingLevel":"h2","heading":"Tatil Bölgelerine Transfer","body":"Kemer''in butik otelleri, Belek''in lüks resort''ları, Side''nin tarihi atmosferi ve Alanya''nın sahil tatil köylerine direkt transfer hizmetimiz mevcuttur. Antalya şehir merkezi, Kaleiçi ve Lara bölgelerine de aynı konforlu hizmet sunulmaktadır."},{"id":"antalya-villa-otel","headingLevel":"h2","heading":"Otel ve Özel Villa Transferleri","body":"Lüks resort''larda veya özel villalarda tatil yapanlar için check-in ve check-out süreçlerinde zamanlama büyük önem taşır. Özel araç ile tam istediğiniz saatte, bagajlarınızı taşıtmadan, kapıdan kapıya rahatlık içinde hareket edebilirsiniz."},{"id":"antalya-mesafe","headingLevel":"h2","heading":"Mesafe ve Güzergah Bilgisi","body":"Antalya Havalimanı''ndan Kemer yaklaşık 45–60 dakika, Belek 30–40 dakika, Side 60–70 dakika ve Alanya ise trafik koşullarına bağlı olarak yaklaşık 2 saatte ulaşılmaktadır. Rezervasyon sırasında güzergah bilgisi paylaşılır."}],"serviceArea":{"title":"Hizmet Verilen Bölgeler","description":"Antalya Havalimanı''ndan Akdeniz''in tüm popüler tatil bölgelerine transfer hizmeti sunulmaktadır.","areas":["Kemer","Belek","Side","Alanya","Kaş","Kalkan","Lara","Kundu","Beldibi","Çamyuva","Kiris","Kızılot","Antalya Şehir Merkezi","Kaleiçi"]},"faqs":[{"id":"antalya-faq-1","question":"Antalya Havalimanı''ndan Belek''e transfer yapıyor musunuz?","answer":"Evet. Belek başta olmak üzere Kemer, Side, Alanya ve tüm Akdeniz tatil bölgelerine transfer hizmeti verilmektedir."},{"id":"antalya-faq-2","question":"Dönüş transferini de siz yapıyor musunuz?","answer":"Evet. Otelden ya da villadan havalimanına dönüş transferi de aynı hizmet kalitesiyle sağlanmaktadır."},{"id":"antalya-faq-3","question":"Büyük grup veya fazla bagajla seyahat ediyoruz, hangi aracı seçmeliyiz?","answer":"Mercedes Sprinter geniş bagaj kapasitesiyle büyük gruplar ve fazla bagaj için idealdir. Kişi sayısı ve bagaj miktarını rezervasyon sırasında belirtmeniz yeterlidir."},{"id":"antalya-faq-4","question":"Uçuşum gecikirse ne olur?","answer":"Uçuş takibi yapılmaktadır. Gecikme durumunda şoförümüz güncel iniş saatinize göre bekler; ekstra ücret talep edilmez."},{"id":"antalya-faq-5","question":"Erken sabah veya gece geç uçuşlarda hizmet alabilir miyim?","answer":"7/24 hizmet verilmektedir. Tatil sezonunda da kesintisiz çalışmaktayız."}],"schemaExtras":{"serviceType":"Airport Transfer","openingHours":"Mo-Su 00:00-24:00","availableLanguage":["Turkish","English","German","Russian"]}}'::jsonb,
  '/hero-images/antalya-vip-transfer.jpg', '/hero-images/antalya-vip-transfer.jpg', 'Antalya VIP Transfer',
  'Antalya VIP Transfer | Havalimanı Özel Araç Hizmeti', 'Antalya Havalimanı''ndan Kemer, Belek, Side, Alanya ve şehir merkezine Mercedes ile VIP transfer. 7/24, kapıdan kapıya özel araç.',
  'PUBLISHED', true, true, 16,
  'airport', true,
  now(), now(), now()
)
ON CONFLICT (slug) DO NOTHING;

INSERT INTO content (
  content_type, title, slug, excerpt, body,
  og_image, hero_image, hero_image_alt,
  seo_title, seo_description,
  status, is_active, indexable, display_order,
  category, show_on_homepage,
  published_at, created_at, updated_at
) VALUES (
  'SERVICE', 'İzmir VIP Transfer', 'izmir-vip-transfer', 'İzmir Adnan Menderes Havalimanı ve şehir içi VIP transfer hizmeti. Mercedes Vito ve Sprinter ile Çeşme, Alaçatı, Bodrum ve şehir merkezine özel araç.', '{"version":2,"hero":{"badge":"İzmir VIP Transfer","title":"İzmir VIP Transfer Hizmeti","subtitle":"İzmir Adnan Menderes Havalimanı''ndan Çeşme, Alaçatı, Urla, Karşıyaka ve tüm Ege güzergahlarına Mercedes Vito ve Sprinter ile konforlu, özel VIP transfer hizmeti.","crumb":"İzmir VIP Transfer","ctaPrimary":"Rezervasyon ve Fiyat","ctaSecondary":"Hemen Ara"},"features":["İzmir Adnan Menderes''te karşılama tabelası","Çeşme, Alaçatı, Urla''ya direkt transfer","Şehir merkezi, Alsancak, Karşıyaka''ya ulaşım","Otel, tatil evi ve marina kapısına teslim","Uçuş takibi ile gecikme koruması","7/24 hizmet — Ege sezonu boyunca kesintisiz"],"seo":{"ogTitle":"İzmir VIP Transfer | Çeşme, Alaçatı, Adnan Menderes","ogDescription":"İzmir Adnan Menderes Havalimanı''ndan Çeşme, Alaçatı ve şehir merkezine Mercedes araçla özel VIP transfer. 7/24 hizmet."},"introBody":"İzmir, Ege''nin incisi olarak hem iş dünyası hem de turizm açısından yoğun hareket gören bir şehirdir. Adnan Menderes Havalimanı''ndan Alsancak, Konak, Karşıyaka ya da Çeşme-Alaçatı bölgesine özel araç transferi, şehrin ve çevresinin en konforlu ulaşım seçeneğidir.","contentSections":[{"id":"izmir-havalimani","headingLevel":"h2","heading":"Adnan Menderes Havalimanı Karşılama","body":"İzmir Adnan Menderes Havalimanı (ADB), şehir merkezine yakın konumuyla öne çıkar. Uçuş bilgilerinizi paylaşmanız yeterlidir; şoförümüz uçuş takibi yaparak tam zamanında dış kapıda hazır olur."},{"id":"izmir-cesme-alacati","headingLevel":"h2","heading":"Çeşme ve Alaçatı Transferleri","body":"Çeşme yarımadası, Alaçatı''nın taş sokakları ve plajları her yıl çok sayıda ziyaretçi çekmektedir. Havalimanından Çeşme ve Alaçatı''ya yaklaşık 60–75 dakikalık bir yol söz konusudur. Özel araç bu güzergahın en rahat ve doğrudan yolculuk seçeneğidir."},{"id":"izmir-sehir-ici","headingLevel":"h2","heading":"İzmir Şehir İçi Transfer","body":"Alsancak, Konak, Bornova, Karşıyaka, Buca, Balçova ve İzmir''in tüm ilçelerine özel araç hizmetimiz bulunmaktadır. Kurumsal toplantılar, fuar ziyaretleri ve otel transferleri için saatlik ya da güzergah bazlı araç tahsisi yapılabilmektedir."},{"id":"izmir-istanbul-transfer","headingLevel":"h2","heading":"İstanbul–İzmir Şehirlerarası Transfer","body":"İstanbul ve İzmir arasında uzun mesafeli özel araç transferi de hizmet kapsamımızdadır. Kendi adresinizden alım yapılır; aktarma veya terminal bekleme olmadan İzmir''deki hedefinize ulaşırsınız."}],"serviceArea":{"title":"Hizmet Verilen Bölgeler","description":"İzmir Adnan Menderes Havalimanı ve Ege''nin önemli destinasyonlarına özel transfer hizmeti verilmektedir.","areas":["Alsancak","Konak","Karşıyaka","Bornova","Buca","Balçova","Çeşme","Alaçatı","Urla","Foça","Seferihisar","Selçuk (Efes)","Kuşadası"]},"faqs":[{"id":"izmir-faq-1","question":"Adnan Menderes''ten Çeşme''ye transfer yapıyor musunuz?","answer":"Evet. Çeşme, Alaçatı ve yarımadanın tüm noktalarına transfer hizmetimiz mevcuttur."},{"id":"izmir-faq-2","question":"İzmir''den İstanbul''a araçla gidebilir miyim?","answer":"Evet. İzmir merkezli ya da İzmir–İstanbul arası şehirlerarası özel araç transferi de sunulmaktadır."},{"id":"izmir-faq-3","question":"Uçuşum gecikirse araç bekler mi?","answer":"Evet. Uçuş takibi yapılmaktadır; gecikme durumunda şoförümüz güncel iniş saatinize göre bekler."},{"id":"izmir-faq-4","question":"Erken sabah uçuşları için hizmet var mı?","answer":"7/24 hizmet sunulmaktadır. Erken ya da gece geç saatteki uçuşlar için de aynı standartta karşılama yapılır."},{"id":"izmir-faq-5","question":"Fuar İzmir''e yakın otellere transfer yapıyor musunuz?","answer":"Evet. Fuar bölgesi dahil İzmir''in tüm ilçelerine ve otellerine transfer hizmeti verilmektedir."}],"schemaExtras":{"serviceType":"Airport Transfer","openingHours":"Mo-Su 00:00-24:00","availableLanguage":["Turkish","English"]}}'::jsonb,
  '/hero-images/izmir-vip-transfer.jpg', '/hero-images/izmir-vip-transfer.jpg', 'İzmir VIP Transfer',
  'İzmir VIP Transfer | Adnan Menderes Havalimanı Özel Araç', 'İzmir Adnan Menderes Havalimanı''ndan Çeşme, Alaçatı, Urla ve şehir merkezine Mercedes ile özel VIP transfer. 7/24, kapıdan kapıya.',
  'PUBLISHED', true, true, 17,
  'airport', true,
  now(), now(), now()
)
ON CONFLICT (slug) DO NOTHING;

INSERT INTO content (
  content_type, title, slug, excerpt, body,
  og_image, hero_image, hero_image_alt,
  seo_title, seo_description,
  status, is_active, indexable, display_order,
  category, show_on_homepage,
  published_at, created_at, updated_at
) VALUES (
  'SERVICE', 'Gelin Arabası Kiralama', 'gelin-arabasi-kiralama', 'Düğününüz için lüks gelin arabası kiralama hizmeti. Mercedes Vito ve Sprinter ile özel süsleme seçenekleri, profesyonel şoför ve 7/24 destek.', '{"version":2,"hero":{"badge":"Düğün & Gelin Arabası","title":"Gelin Arabası Kiralama","subtitle":"En özel gününüzde konfor ve zarafeti bir arada sunuyoruz. Mercedes Vito ve Sprinter ile lüks düğün transferi — özel süsleme, profesyonel şoför ve dikkat çeken bir varış.","crumb":"Gelin Arabası Kiralama","ctaPrimary":"Fiyat ve Rezervasyon","ctaSecondary":"Hemen Ara"},"features":["Özel gün temasına uygun araç süslemesi","Deneyimli ve takım elbiseli profesyonel şoför","Nikâh, nikâh sonrası ve düğün töreni transferleri","Gelin ve damat için ayrı veya birlikte transfer seçeneği","Fotoğraf çekimi için araç eşliği imkânı","7/24 rezervasyon ve destek hattı"],"seo":{"ogTitle":"Gelin Arabası Kiralama İstanbul | Lüks Düğün Mercedes","ogDescription":"İstanbul''da Mercedes Vito ve Sprinter ile lüks gelin arabası kiralama. Özel süsleme, profesyonel şoför, düğün töreni transferleri."},"introBody":"Düğün günü, hayatınızın en özel anlarından biridir. Bu özel günde ulaşımın da aynı özenle planlanması gerekir. Özel süslemeli Mercedes Vito ya da Sprinter ile nikâh salonundan töreninize, töreninizden düğün mekânınıza ve gece sonu otele kadar kusursuz bir geçiş sağlanır. Profesyonel şoförümüz tüm gün yanınızda olur; planlama ve zamanlama konusunda da destek alırsınız.","contentSections":[{"id":"gelin-susleme","headingLevel":"h2","heading":"Araç Süsleme Seçenekleri","body":"Düğün temanıza uygun çiçek aranjmanı, kurdeleler ve özel süslemeler ile araç hazırlanabilmektedir. Beyaz, krem, pastel tonlar ya da özel renk temanıza göre düzenleme yapılabilir. Süsleme detayları rezervasyon öncesinde koordine edilmektedir."},{"id":"gelin-transfer-planlama","headingLevel":"h2","heading":"Düğün Günü Transfer Planlaması","body":"Nikâh salonuna geliş, törenden sonra düğün mekânına geçiş ve gece sonu otele ya da damat evine transfer — tüm bu süreçler önceden planlanır ve şoförünüz programa uygun olarak hazır bulunur. Birden fazla araç gerekiyorsa koordineli planlama yapılabilmektedir."},{"id":"gelin-fotograf","headingLevel":"h2","heading":"Fotoğraf ve Video Çekimi için Araç Eşliği","body":"Dış çekim sırasında araç ve şoförünüz fotoğraf çekimi mekanlarında bekler, güzergahta eşlik eder. Bu sayede hem ulaşım sorunu yaşanmaz hem de düğün fotoğraflarınıza zarif bir araç arka plan olabilir."},{"id":"gelin-neden-biz","headingLevel":"h2","heading":"Neden Özel Düğün Aracı?","body":"En özel gününüzde oluşabilecek ulaşım aksaklıkları, gecikme veya plansız durumlar stres yaratır. Deneyimli bir şoförle planlanmış ve zamanında işleyen bir transfer, düğün gününüzün sorunsuz akmasına doğrudan katkı sağlar."}],"serviceArea":{"title":"Hizmet Kapsamı","description":"İstanbul ve çevresindeki tüm ilçelere düğün transferi ve gelin arabası hizmeti verilmektedir.","areas":["Taksim","Beşiktaş","Şişli","Kadıköy","Üsküdar","Sarıyer","Beykoz","Ataşehir","Bostancı","Florya","Yeşilköy","Pendik","Sultanahmet","Bakırköy"]},"faqs":[{"id":"gelin-faq-1","question":"Araç özel olarak süsleniyor mu?","answer":"Evet. Düğün temanıza uygun çiçek aranjmanı ve süsleme rezervasyon öncesi koordine edilmektedir. Renk ve tarz tercihlerinizi paylaşmanız yeterlidir."},{"id":"gelin-faq-2","question":"Nikâhtan düğüne kadar araç tüm gün bizimle olur mu?","answer":"Evet. Günlük kiralama seçeneği ile şoförünüz belirttiğiniz zaman dilimi boyunca yanınızda olur. Tüm geçişleri zamanında gerçekleştirir."},{"id":"gelin-faq-3","question":"Vito mu Sprinter mi tercih edilmeli?","answer":"Gelin ve damat için daha samimi bir atmosfer istiyorsanız Vito tercih edilebilir. Büyük gelin alayı veya grup transferleri için Sprinter daha uygundur."},{"id":"gelin-faq-4","question":"Fotoğraf çekimi için araç eşliği alabilir miyim?","answer":"Evet. Dış çekim sırasında araç ve şoförünüz belirlenen mekan veya güzergahlarda eşlik edebilir."},{"id":"gelin-faq-5","question":"İstanbul dışı düğünlerde de hizmet alabilir miyim?","answer":"İstanbul ve çevre illerdeki düğün mekânlarına da hizmet verilmektedir. Güzergahı rezervasyon sırasında paylaşmanız yeterlidir."}],"schemaExtras":{"serviceType":"Chauffeur Service","openingHours":"Mo-Su 00:00-24:00","availableLanguage":["Turkish","English"]}}'::jsonb,
  '/hero-images/gelin-arabasi-kiralama.jpg', '/hero-images/gelin-arabasi-kiralama.jpg', 'Gelin Arabası Kiralama',
  'Gelin Arabası Kiralama İstanbul | Düğün Mercedes VIP', 'İstanbul''da lüks gelin arabası kiralama. Mercedes Vito ve Sprinter ile düğün transferi, özel süsleme, profesyonel şoför. En özel gününüz için.',
  'PUBLISHED', true, true, 18,
  'rental', true,
  now(), now(), now()
)
ON CONFLICT (slug) DO NOTHING;

INSERT INTO content (
  content_type, title, slug, excerpt, body,
  og_image, hero_image, hero_image_alt,
  seo_title, seo_description,
  status, is_active, indexable, display_order,
  category, show_on_homepage,
  published_at, created_at, updated_at
) VALUES (
  'SERVICE', 'VIP Protokol ve Seçim Aracı', 'vip-protokol-secim-araci', 'Kurumsal ve siyasi etkinlikler ile seçim kampanyaları için özel şoförlü VIP araç tahsisi. Protokol transferleri, diskret ve profesyonel hizmet.', '{"version":2,"hero":{"badge":"Protokol & Kurumsal VIP","title":"VIP Protokol ve Seçim Aracı Hizmeti","subtitle":"Kurumsal, siyasi ve protokol etkinlikleri için diskret, güvenilir ve profesyonel özel şoförlü VIP araç tahsisi. Seçim kampanyaları ve sahaya çıkış organizasyonları için planlanmış ulaşım.","crumb":"VIP Protokol Aracı","ctaPrimary":"Fiyat ve Rezervasyon","ctaSecondary":"Hemen Ara"},"features":["Diskret ve profesyonel şoför hizmeti","Çoklu nokta ve esnek güzergah planlaması","Uzun süreli araç tahsisi — günlük veya haftalık","Protokol etkinlikleri için koordineli araç filosu","Gizlilik odaklı hizmet anlayışı","7/24 hazır bulunurluk ve destek"],"seo":{"ogTitle":"VIP Protokol Aracı | Siyasi Kampanya Araç Tahsisi","ogDescription":"Protokol transferleri ve seçim kampanyaları için Mercedes Vito/Sprinter ile diskret VIP araç tahsisi. Profesyonel şoför, esnek güzergah."},"introBody":"Protokol transferleri ve siyasi kampanya süreçleri, ulaşım planlamasında hassas zamanlamayı, diskreti ve güvenilirliği bir arada gerektirir. Kurumsal etkinlikler, büyükelçilik transferleri, kamu yöneticisi ziyaretleri ve seçim kampanya sahaya çıkışları için uzun süreli araç ve şoför tahsisi yapılabilmektedir. Tüm hizmetlerimizde gizlilik ve profesyonellik ön plandadır.","contentSections":[{"id":"protokol-etkinlik","headingLevel":"h2","heading":"Protokol ve Kurumsal Etkinlik Transferleri","body":"Devlet etkinlikleri, uluslararası kongre ve zirveler, büyükelçilik ziyaretleri ve kurumsal törenler için araç planlaması yapılmaktadır. Birden fazla araç gerektiğinde koordineli filo düzenlemesi de sağlanabilmektedir."},{"id":"protokol-secim","headingLevel":"h2","heading":"Seçim Kampanyası Araç Tahsisi","body":"Seçim dönemi sahaya çıkış programları, mitingler ve seçim bölgesi ziyaretleri için günlük ya da haftalık bazda araç ve şoför tahsisi yapılmaktadır. Yoğun programlarda birden fazla araç koordinasyonu da sağlanabilmektedir. Güzergah ve program değişikliklerine esneklikle uyum sağlanır."},{"id":"protokol-diskret","headingLevel":"h2","heading":"Diskret Hizmet Anlayışı","body":"Üst düzey yöneticiler, siyasetçiler ve kamuoyunda tanınan bireyler için ulaşım organizasyonlarında gizlilik, güvenilirlik ve dikkat dağıtmayan bir profesyonellik esastır. Şoförlerimiz bu gerekliliklere uygun eğitimli ve deneyimlidir."},{"id":"protokol-filo","headingLevel":"h2","heading":"Çoklu Araç ve Filo Organizasyonu","body":"Büyük ölçekli protokol organizasyonlarında birden fazla araç ve şoförün koordineli çalışması gerekebilir. Zaman çizelgesi, alım noktaları ve güzergahlar önceden planlanır; iletişim tek noktadan yürütülür."}],"serviceArea":{"title":"Hizmet Kapsamı","description":"İstanbul başta olmak üzere Ankara ve diğer şehirlerde protokol ve kampanya araç hizmetleri sunulmaktadır.","areas":["İstanbul Tüm İlçeler","Ankara","İzmir","Bursa","Antalya","Büyükelçilik Bölgeleri","Kongre Merkezleri","Havalimanı Transferleri"]},"faqs":[{"id":"protokol-faq-1","question":"Haftalık ya da aylık araç tahsisi yapıyor musunuz?","answer":"Evet. Seçim kampanyaları ve uzun süreli etkinlikler için günlük, haftalık ya da daha uzun süreli araç ve şoför tahsisi planlanabilmektedir."},{"id":"protokol-faq-2","question":"Birden fazla araç ihtiyacımız olursa koordine edebilir misiniz?","answer":"Evet. Filo düzenlemesi yapılabilmektedir; tüm araçların koordinasyonu tek noktadan yönetilir."},{"id":"protokol-faq-3","question":"Şoförler gizlilik konusunda güvenilir mi?","answer":"Evet. Şoförlerimiz diskret hizmet anlayışını benimsemiş ve deneyimli profesyonellerdir."},{"id":"protokol-faq-4","question":"Program değişirse araç uyum sağlayabiliyor mu?","answer":"Evet. Günlük tahsisli araçlarda program değişikliklerine esneklikle uyum sağlanmaktadır. Şoförünüz tüm gün hazır bulunur."},{"id":"protokol-faq-5","question":"Ankara veya diğer şehirlerde de hizmet sunuyor musunuz?","answer":"Evet. İstanbul''a ek olarak Ankara, İzmir ve diğer büyük şehirlerde de protokol ve kampanya araç hizmeti verilebilmektedir."}],"schemaExtras":{"serviceType":"Chauffeur Service","openingHours":"Mo-Su 00:00-24:00","availableLanguage":["Turkish","English"]}}'::jsonb,
  '/hero-images/vip-protokol-secim-araci.jpg', '/hero-images/vip-protokol-secim-araci.jpg', 'VIP Protokol ve Seçim Aracı',
  'VIP Protokol Aracı | Seçim Kampanya Araç Kiralama', 'Protokol transferleri ve seçim kampanyaları için özel şoförlü VIP araç tahsisi. Mercedes Vito ve Sprinter, diskret profesyonel hizmet.',
  'PUBLISHED', true, true, 19,
  'corporate', true,
  now(), now(), now()
)
ON CONFLICT (slug) DO NOTHING;

INSERT INTO content (
  content_type, title, slug, excerpt, body,
  og_image, hero_image, hero_image_alt,
  seo_title, seo_description,
  status, is_active, indexable, display_order,
  category, show_on_homepage,
  published_at, created_at, updated_at
) VALUES (
  'SERVICE', 'Günlük Villa Kiralama', 'gunluk-villa-kiralama', 'İstanbul çevresinde günlük kiralık VIP villa hizmeti. Transfer desteğiyle birlikte — doğa içinde, lüks ve özel bir konaklama deneyimi.', '{"version":2,"hero":{"badge":"Günlük VIP Villa","title":"Günlük Villa Kiralama Hizmeti","subtitle":"İstanbul çevresinin sakin güzelliklerinde günlük kiralık lüks villa. Özel bahçe, havuz ve korunaklı alanlar — transfer hizmetiyle kapıdan kapıya rahatlık.","crumb":"Günlük Villa Kiralama","ctaPrimary":"Fiyat ve Rezervasyon","ctaSecondary":"Hemen Ara"},"features":["İstanbul çevresinde özel havuzlu villa seçenekleri","Günlük veya kısa süreli kiralama","Transfer hizmetiyle birlikte alım ve bırakma","Şirket toplantısı, aile buluşması ve özel etkinlikler için","Korunaklı ve gizli alan — kamusal kalabalığa uzak","Önceden planlama ve programlama desteği"],"seo":{"ogTitle":"Günlük Villa Kiralama İstanbul | Özel Havuzlu VIP Villa","ogDescription":"İstanbul çevresinde günlük lüks villa kiralama. Özel havuz, bahçe, transfer dahil."},"introBody":"İstanbul''un kalabalığından uzaklaşarak özel ve sakin bir ortamda günlük toplantı, aile buluşması ya da özel etkinlik düzenlemek isteyenler için günlük villa kiralama hizmeti sunulmaktadır. Transfer hizmetiyle birlikte rezervasyon yaparak ulaşım sorununu da ortadan kaldırabilirsiniz.","contentSections":[{"id":"villa-kullanim","headingLevel":"h2","heading":"Günlük Villa Kimler İçin?","body":"Kurumsal team-building etkinlikleri, şirket toplantıları; özel kutlamalar, doğum günleri ve yıldönümleri; aile buluşmaları; fotoğraf ve video çekimleri için uygun seçenekler mevcuttur."},{"id":"villa-lokasyon","headingLevel":"h2","heading":"İstanbul Çevresinde Villa Bölgeleri","body":"Şile, Ağva, Polonezköy, Beykoz ormanları ve Boğaz çevresi gibi İstanbul''a yakın bölgeler öne çıkan villa destinasyonlarıdır."},{"id":"villa-transfer","headingLevel":"h2","heading":"Transfer ile Kombine Hizmet","body":"Villa kiralama hizmetimizi Mercedes Vito veya Sprinter ile özel araç transferiyle birleştirebilirsiniz. Tüm grubunuzu alarak villaya bırakır, etkinlik sonunda geri getiririz."},{"id":"villa-etkinlik","headingLevel":"h2","heading":"Etkinlik Organizasyonu Desteği","body":"Villa kiralama ve transfer birlikte planlandığında tüm organizasyon tek noktadan yönetilir."}],"serviceArea":{"title":"Hizmet Kapsamı","description":"İstanbul''a yakın villa bölgeleri ve çevre destinasyonlara transfer hizmetiyle ulaşım.","areas":["Şile","Ağva","Polonezköy","Beykoz","Boğaz Çevresi","Büyükçekmece","Silivri","Çatalca","Sapanca","Abant"]},"faqs":[{"id":"villa-faq-1","question":"Villa kiralama ve transfer birlikte rezervasyon yapılabiliyor mu?","answer":"Evet. Villa rezervasyonunuzu transfer hizmetiyle birleştirebilirsiniz."},{"id":"villa-faq-2","question":"Minimum kiralama süresi ne kadar?","answer":"Günlük kiralama esasına göre hizmet verilmektedir."},{"id":"villa-faq-3","question":"Kurumsal etkinlikler için villa var mı?","answer":"Evet. Şirket toplantıları ve team-building için uygun villa seçenekleri koordine edilebilir."},{"id":"villa-faq-4","question":"Havuzlu villa bulunabilir mi?","answer":"Evet. Özel havuzlu villa seçenekleri mevcuttur."},{"id":"villa-faq-5","question":"Kaç kişiyle gidebiliriz?","answer":"Kişi sayısına göre hem villa kapasitesi hem de araç seçimi planlanır. Mercedes Sprinter ile büyük gruplar rahatlıkla transfer edilebilir."}],"schemaExtras":{"serviceType":"Event Space Rental","openingHours":"Mo-Su 00:00-24:00","availableLanguage":["Turkish","English"]}}'::jsonb,
  '/hero-images/gunluk-villa-kiralama.jpg', '/hero-images/gunluk-villa-kiralama.jpg', 'Günlük Villa Kiralama',
  'Günlük Villa Kiralama İstanbul | VIP Günübirlik Villa', 'İstanbul çevresinde günlük kiralık lüks villa. Özel havuz, bahçe, korunaklı alan ve transfer hizmetiyle birlikte özel konaklama deneyimi.',
  'PUBLISHED', true, true, 20,
  'rental', true,
  now(), now(), now()
)
ON CONFLICT (slug) DO NOTHING;
